// HeroSection component
import React from 'react';
import Image from 'next/image';
import Link from 'next/link';
import { getFeaturedNews, getAllNews } from '@/lib/supabase';

const HeroSection: React.FC = async () => {
  const featuredNews = await getFeaturedNews();
  const allNews = await getAllNews();

  // If no featured news, show default content
  if (featuredNews.length === 0) {
    return (
      <section className="bg-background py-8">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center py-16">
            <h2 className="text-3xl font-bold text-primary mb-4">DikiliHaber'e Hoş Geldiniz</h2>
            <p className="text-gray-600 mb-8">En güncel haberler için admin panelinden öne çıkan haberlerinizi ekleyin.</p>
            <Link href="/admin" className="bg-primary text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition">
              Admin Paneline Git
            </Link>
          </div>
        </div>
      </section>
    );
  }

  const mainNews = featuredNews[0];
  const sideNews = featuredNews.slice(1);

  const trendingNews = allNews.length > 4 ? allNews.slice(3, 7).map((news, index) => ({
    id: news.id,
    title: news.title,
    category: news.category,
    slug: news.slug,
    views: `${Math.floor(Math.random() * 20) + 5}.${Math.floor(Math.random() * 9) + 1}K`,
  })) : [
    { id: '1', title: 'Trend Haber 1', category: 'Ekonomi', slug: 'trend-haber-1', views: '12.5K' },
    { id: '2', title: 'Trend Haber 2', category: 'Spor', slug: 'trend-haber-2', views: '8.3K' },
    { id: '3', title: 'Trend Haber 3', category: 'Magazin', slug: 'trend-haber-3', views: '15.2K' },
    { id: '4', title: 'Trend Haber 4', category: 'Teknoloji', slug: 'trend-haber-4', views: '9.7K' },
  ];

  return (
    <section className="bg-background py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Featured News */}
          <div className="lg:col-span-2">
            <div className="relative h-96 lg:h-[500px] rounded-lg overflow-hidden shadow-2xl">
              <Image
                src={featuredNews[0].image_url}
                alt={featuredNews[0].title}
                fill
                className="object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black via-black/50 to-transparent">
                <div className="absolute bottom-0 left-0 right-0 p-8 text-white">
                  <span className="inline-block bg-accent text-white px-4 py-2 rounded-full text-sm font-semibold mb-4 shadow-lg">
                    {featuredNews[0].category}
                  </span>
                  <h2 className="text-3xl lg:text-4xl font-bold leading-tight mb-4 drop-shadow-lg">
                    {featuredNews[0].title}
                  </h2>
                  <p className="text-lg text-gray-200 mb-6 line-clamp-2">
                    {featuredNews[0].excerpt}
                  </p>
                  <Link href={`/news/${featuredNews[0].slug}`} className="inline-block bg-primary hover:bg-blue-700 text-white px-6 py-3 rounded-lg font-semibold transition-colors duration-300 shadow-lg">
                    Devamını Oku
                  </Link>
                </div>
              </div>
            </div>
          </div>

          {/* Trending List - Enhanced */}
          <div className="bg-white rounded-xl shadow-xl p-6 border border-gray-100">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold text-primary">🔥 Trend Haberler</h3>
              <span className="text-sm text-gray-500">Canlı</span>
            </div>
            <ul className="space-y-4">
              {trendingNews.map((news, index) => (
                <li key={news.id}>
                  <Link href={`/news/${news.slug}`} className="group block cursor-pointer p-3 rounded-lg hover:bg-gray-50 transition-colors duration-200">
                    <div className="flex items-start space-x-3">
                      <span className="flex-shrink-0 w-8 h-8 bg-gradient-to-r from-accent to-red-500 text-white rounded-full flex items-center justify-center text-sm font-bold shadow-md">
                        {index + 1}
                      </span>
                      <div className="flex-1 min-w-0">
                        <span className="text-xs text-accent font-semibold uppercase tracking-wider mb-1 block">
                          {news.category}
                        </span>
                        <h4 className="text-sm font-semibold text-gray-900 leading-tight group-hover:text-primary transition-colors line-clamp-2">
                          {news.title}
                        </h4>
                        <div className="flex items-center mt-2 text-xs text-gray-500">
                          <span>{news.views} görüntülenme</span>
                        </div>
                      </div>
                    </div>
                  </Link>
                </li>
              ))}
            </ul>
            <button className="w-full mt-6 bg-primary hover:bg-blue-700 text-white py-2 rounded-lg font-medium transition-colors duration-200">
              Tüm Trendleri Gör
            </button>
          </div>
        </div>
      </div>
    </section>
  );
};

export default HeroSection;